const fs = require("fs");
const html = fs.readFileSync("index.html", "utf8");
const script = html.split("<script>")[1].split("</script>")[0];
const fn = new Function(script + "\nreturn { OFFICIAL_ELEMENTS, RAW_RECIPES, ACHIEVEMENTS };");
const { OFFICIAL_ELEMENTS, RAW_RECIPES, ACHIEVEMENTS } = fn();
console.log("Total official elements:", OFFICIAL_ELEMENTS.length);
const ids = new Set(OFFICIAL_ELEMENTS.map(e => e.id));
const bad = [];
const pairSeen = new Map();
const dups = [];
for (const [a, b, c] of RAW_RECIPES) {
  if (!ids.has(a) || !ids.has(b) || !ids.has(c)) bad.push([a, b, c]);
  const key = [a, b].sort().join("+");
  if (pairSeen.has(key) && pairSeen.get(key) !== c) {
    dups.push([key, pairSeen.get(key), c]);
  }
  pairSeen.set(key, c);
}
console.log("Invalid IDs in recipes:", bad);
console.log("Conflicting duplicate pairs:", dups);

// BFS reachability
const discovered = new Set(OFFICIAL_ELEMENTS.filter(e => e.starter).map(e => e.id));
const depth = {};
for (const d of discovered) depth[d] = 0;
let changed = true;
while (changed) {
  changed = false;
  for (const [a, b, c] of RAW_RECIPES) {
    if (ids.has(a) && ids.has(b) && ids.has(c)) {
      const key = [a, b].sort().join("+");
      const winner = pairSeen.get(key);
      if (winner === c && discovered.has(a) && discovered.has(b) && !discovered.has(c)) {
        discovered.add(c);
        depth[c] = Math.max(depth[a], depth[b]) + 1;
        changed = true;
      }
    }
  }
}
const unreachable = OFFICIAL_ELEMENTS.filter(e => !discovered.has(e.id)).map(e => e.id);
console.log("Reachable:", discovered.size, "/", OFFICIAL_ELEMENTS.length);
console.log("Unreachable:", unreachable);
console.log("Max depth:", Math.max(...Object.values(depth)));
'

