// === SECTION 2: ENGINE ===
const STORAGE_KEY = "web_reactiva_craft_v1";

// Build fast lookup maps
const ELEMENT_MAP = new Map();
for (const el of OFFICIAL_ELEMENTS) {
  ELEMENT_MAP.set(el.id, { ...el, official: true });
}

const RECIPE_MAP = new Map();
function pairKey(a, b) {
  return a < b ? `${a}+${b}` : `${b}+${a}`;
}
for (const [a, b, res] of RAW_RECIPES) {
  const k = pairKey(a, b);
  if (!RECIPE_MAP.has(k)) {
    RECIPE_MAP.set(k, res);
  }
}

// --- Web Audio Procedural Sound Synth (Zero external assets) ---
class SoundFX {
  constructor() {
    this.enabled = true;
    this.ctx = null;
  }
  init() {
    if (!this.ctx && (window.AudioContext || window.webkitAudioContext)) {
      const AC = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AC();
    }
    if (this.ctx && this.ctx.state === "suspended") {
      this.ctx.resume();
    }
  }
  tone(freq, type = "sine", dur = 0.12, gainVal = 0.08, delay = 0, slideTo = null) {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slideTo) {
      osc.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
    }
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.linearRampToValueAtTime(gainVal, t0 + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }
  pickup() {
    this.tone(360, "sine", 0.07, 0.06, 0, 520);
  }
  drop() {
    this.tone(300, "triangle", 0.07, 0.05, 0, 220);
  }
  delete() {
    this.tone(240, "sine", 0.09, 0.05, 0, 120);
  }
  fail() {
    this.tone(210, "sawtooth", 0.09, 0.035, 0, 175);
    this.tone(170, "sawtooth", 0.11, 0.035, 0.08, 140);
  }
  combine() {
    this.tone(440, "triangle", 0.12, 0.07, 0);
    this.tone(554.37, "triangle", 0.15, 0.07, 0.05);
  }
  discover(isMilestone = false) {
    const notes = isMilestone ? [523.25, 659.25, 783.99, 1046.5] : [493.88, 659.25, 880];
    notes.forEach((n, idx) => {
      this.tone(n, "triangle", 0.24, 0.085, idx * 0.065);
    });
  }
}
const sfx = new SoundFX();

// --- Deterministic Procedural Malandriner Fusion Engine (Modo Infinito) ---
function hashStr(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

const PROC_TEMPLATES = [
  { fmt: (a, b) => `${a} Malandriner de ${b}`, emojis: ["⚡", "🕵️", "🔧", "🚀"] },
  { fmt: (a, b) => `Micro-${a} con ${b}`, emojis: ["🧪", "🛠️", "📦", "✨"] },
  { fmt: (a, b) => `${a} Automatizado`, sub: (a, b) => `${a} + ${b}`, emojis: ["⚙️", "🟣", "🔄", "🤖"] },
  { fmt: (a, b) => `SaaS de ${a} y ${b}`, emojis: ["💼", "💸", "📈", "🦄"] },
  { fmt: (a, b) => `Podcast sobre ${a}`, emojis: ["🎙️", "🎧", "📻", "🗣️"] },
  { fmt: (a, b) => `${a} en Producción`, emojis: ["🔥", "🔒", "🚨", "🐳"] },
  { fmt: (a, b) => `Plugin de ${a} para ${b}`, emojis: ["🔌", "🧩", "📝", "💻"] },
  { fmt: (a, b) => `Agente de ${a}`, emojis: ["🕵️‍♂️", "🧠", "🤖", "🔮"] },
  { fmt: (a, b) => `Boletín de ${a} & ${b}`, emojis: ["📩", "✍️", "📡", "🌱"] },
  { fmt: (a, b) => `Arquitectura ${a}-${b}`, emojis: ["🏗️", "☁️", "🖥️", "🧘"] },
  { fmt: (a, b) => `Reto de ${a} con ${b}`, emojis: ["🏆", "🔥", "🧭", "☕"] },
  { fmt: (a, b) => `Script de ${b} (${a})`, emojis: ["⌨️", "🐧", "⏱️", "🌿"] }
];

const PROC_LORES = [
  "Invento nacido a las 23:45 cacharreando en local con una taza a medio terminar.",
  "Prototipo malandriner que empezó como broma en Telegram y ya tiene tres usuarios fieles.",
  "Fusión experimental digna de protagonizar una sección entera del boletín del martes.",
  "Nadie sabía que necesitaba combinar esto hasta que funcionó a la primera sin bugs.",
  "Solución pragmática, casera y libre de humo lista para enseñarse en el próximo Café Virtual.",
  "Experimento alquímico que Daniel Primo aprobaría con una ceja levantada y una sonrisa."
];

function cleanCoreWord(el) {
  // Extract clean short root noun so procedural names never nest infinitely
  if (el.rootWord) return el.rootWord;
  const stripped = el.name
    .replace(/^(Micro-|SaaS de |Podcast sobre |Plugin de |Agente de |Boletín de |Arquitectura |Reto de |Script de )/i, "")
    .split(/\s+(de|con|para|en|sobre|&)\s+/i)[0]
    .trim();
  return stripped.length > 22 ? stripped.slice(0, 22).trim() : stripped;
}

function createProceduralElement(elA, elB) {
  const key = pairKey(elA.id, elB.id);
  const h = hashStr(key);
  const id = "proc_" + h.toString(36);
  if (ELEMENT_MAP.has(id)) {
    return ELEMENT_MAP.get(id);
  }

  const wA = cleanCoreWord(elA);
  const wB = cleanCoreWord(elB);
  let name = "";
  if (wA.toLowerCase() === wB.toLowerCase()) {
    const prefixes = ["Súper", "Meta", "Hiper", "Ultra", "Turbo", "Mega"];
    name = `${prefixes[h % prefixes.length]} ${wA}`;
  } else {
    const tpl = PROC_TEMPLATES[h % PROC_TEMPLATES.length];
    name = (h & 1) === 0 ? tpl.fmt(wA, wB) : tpl.fmt(wB, wA);
  }

  const tplRef = PROC_TEMPLATES[(h >>> 3) % PROC_TEMPLATES.length];
  const emojiPool = [elA.emoji, elB.emoji, ...tplRef.emojis];
  const emoji = emojiPool[(h >>> 5) % emojiPool.length];
  const lore = PROC_LORES[(h >>> 7) % PROC_LORES.length];

  const customEl = {
    id,
    name,
    emoji,
    cat: "ia",
    official: false,
    procedural: true,
    firstDiscovery: true,
    rootWord: (h & 2) ? wA : wB,
    lore
  };
  ELEMENT_MAP.set(id, customEl);
  return customEl;
}

// --- Game State ---
const state = {
  discovered: ["codigo", "microfono", "cafe", "curiosidad"], // ordered by discovery time
  customElements: {}, // id -> custom element object
  unlockedRecipes: {}, // "a+b" -> resultId
  firstDiscoveries: [], // ids discovered as First Discovery / Milestone
  canvasItems: [], // { uid, id, x, y, firstBadge }
  panX: 0,
  panY: 0,
  zoom: 1,
  infiniteMode: true,
  sound: true,
  theme: "light",
  filter: "all",
  sort: "time",
  search: "",
  activeModalTab: "elements"
};

let uidCounter = 1;

function saveState() {
  try {
    const payload = {
      discovered: state.discovered,
      customElements: state.customElements,
      unlockedRecipes: state.unlockedRecipes,
      firstDiscoveries: state.firstDiscoveries,
      canvasItems: state.canvasItems.slice(-80),
      infiniteMode: state.infiniteMode,
      sound: state.sound,
      theme: state.theme
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
  } catch (_) {}
}

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return false;
    const parsed = JSON.parse(raw);
    if (parsed.customElements && typeof parsed.customElements === "object") {
      state.customElements = parsed.customElements;
      for (const [cid, cel] of Object.entries(parsed.customElements)) {
        ELEMENT_MAP.set(cid, cel);
      }
    }
    if (Array.isArray(parsed.discovered) && parsed.discovered.length >= 4) {
      state.discovered = parsed.discovered.filter(id => ELEMENT_MAP.has(id));
      for (const st of ["codigo", "microfono", "cafe", "curiosidad"]) {
        if (!state.discovered.includes(st)) state.discovered.unshift(st);
      }
    }
    if (parsed.unlockedRecipes) state.unlockedRecipes = parsed.unlockedRecipes;
    if (Array.isArray(parsed.firstDiscoveries)) state.firstDiscoveries = parsed.firstDiscoveries;
    if (typeof parsed.infiniteMode === "boolean") state.infiniteMode = parsed.infiniteMode;
    if (typeof parsed.sound === "boolean") state.sound = parsed.sound;
    if (parsed.theme === "dark" || parsed.theme === "light") state.theme = parsed.theme;
    if (Array.isArray(parsed.canvasItems)) {
      state.canvasItems = parsed.canvasItems.filter(it => ELEMENT_MAP.has(it.id));
    }
    return true;
  } catch (_) {
    return false;
  }
}

// === SECTION 2B: UI & INTERACTIONS ===

