// === SECTION 2B: UI & INTERACTIONS ===
const dom = {
  workspace: document.getElementById("workspace"),
  world: document.getElementById("world"),
  fxCanvas: document.getElementById("fx-canvas"),
  sidebar: document.getElementById("sidebar"),
  inventoryList: document.getElementById("inventory-list"),
  dragGhost: document.getElementById("drag-ghost"),
  emptyGuide: document.getElementById("empty-guide"),
  toastContainer: document.getElementById("toast-container"),
  brandQuote: document.getElementById("brand-quote"),
  statsOfficial: document.getElementById("stats-official"),
  statsExtra: document.getElementById("stats-extra"),
  progressFill: document.getElementById("progress-fill"),
  searchInput: document.getElementById("search-input"),
  searchClear: document.getElementById("search-clear"),
  filterTabs: document.getElementById("filter-tabs"),
  sortSelect: document.getElementById("sort-select"),
  btnInfinite: document.getElementById("btn-infinite"),
