  zoomLabel: document.getElementById("zoom-label"),
  codexModal: document.getElementById("codex-modal"),
  modalClose: document.getElementById("modal-close"),
  modalTabs: document.getElementById("modal-tabs"),
  modalBody: document.getElementById("modal-body")
};

// --- Particle Burst System ---
const fxCtx = dom.fxCanvas.getContext("2d");
const particles = [];

function resizeFxCanvas() {
  const rect = dom.workspace.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  dom.fxCanvas.width = rect.width * dpr;
  dom.fxCanvas.height = rect.height * dpr;
  fxCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
window.addEventListener("resize", resizeFxCanvas);

function spawnParticles(worldX, worldY, isSpecial = false) {
  const sx = worldX * state.zoom + state.panX;
  const sy = worldY * state.zoom + state.panY;
  const colors = isSpecial
    ? ["#facc15", "#f59e0b", "#6366f1", "#ec4899", "#10b981"]
    : ["#6366f1", "#f59e0b", "#3b82f6", "#a855f7"];
  const count = isSpecial ? 34 : 18;
  for (let i = 0; i < count; i++) {
    const angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.4;
    const speed = (isSpecial ? 2.4 : 1.6) + Math.random() * (isSpecial ? 4.2 : 2.6);
    particles.push({
      x: sx,
      y: sy,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed - 0.6,
      r: 2.5 + Math.random() * (isSpecial ? 3.5 : 2.2),
      alpha: 1,
      color: colors[i % colors.length]
    });
  }
}

function tickParticles() {
  if (particles.length > 0) {
    const rect = dom.workspace.getBoundingClientRect();
    fxCtx.clearRect(0, 0, rect.width, rect.height);
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.08;
      p.alpha -= 0.028;
      if (p.alpha <= 0) {
        particles.splice(i, 1);
        continue;
      }
      fxCtx.globalAlpha = p.alpha;
      fxCtx.fillStyle = p.color;
      fxCtx.beginPath();
      fxCtx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      fxCtx.fill();
    }
    fxCtx.globalAlpha = 1;
  }
  requestAnimationFrame(tickParticles);
}

// --- Helper: Compute which discovered elements still have undiscovered official combos ---
function getElementsWithAvailableCombos() {
  const discSet = new Set(state.discovered);
  const hasCombo = new Set();
  for (const [k, resId] of RECIPE_MAP.entries()) {
    if (discSet.has(resId)) continue;
    const [a, b] = k.split("+");
    if (discSet.has(a) && discSet.has(b)) {
      hasCombo.add(a);
      hasCombo.add(b);
    }
  }
  return hasCombo;
}

function countRemainingCombosFor(elId) {
  const discSet = new Set(state.discovered);
  let count = 0;
  for (const [k, resId] of RECIPE_MAP.entries()) {
    if (discSet.has(resId)) continue;
    const [a, b] = k.split("+");
    if ((a === elId && discSet.has(b)) || (b === elId && discSet.has(a))) {
      count++;
    }
  }
  return count;
}

// --- Toast Notifications ---
function showToast({ emoji, tag, title, desc, info = false, actionText = null, onAction = null, duration = 4600 }) {
  while (dom.toastContainer.children.length >= 2) {
    dom.toastContainer.firstChild.remove();
  }
  const card = document.createElement("div");
  card.className = "discovery-toast" + (info ? " info-toast" : "");
  card.innerHTML = `
    <div class="toast-emoji">${emoji}</div>
    <div class="toast-body">
      <div class="toast-tag">${tag}</div>
      <div class="toast-title">${title}</div>
      <div class="toast-desc">${desc}</div>
    </div>
  `;
  if (actionText && onAction) {
    const btn = document.createElement("button");
    btn.className = "toast-action";
    btn.textContent = actionText;
    btn.addEventListener("click", () => {
      onAction();
      card.remove();
    });
    card.querySelector(".toast-body").appendChild(btn);
  }
  dom.toastContainer.appendChild(card);
  setTimeout(() => {
    if (card.parentNode) card.remove();
  }, duration);
}

// --- World Transform (Pan & Zoom) ---
function updateWorldTransform() {
  dom.world.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.zoom})`;
  dom.workspace.style.backgroundPosition = `${state.panX}px ${state.panY}px`;
  const grid = 24 * state.zoom;
  dom.workspace.style.backgroundSize = `${grid}px ${grid}px`;
  dom.zoomLabel.textContent = `${Math.round(state.zoom * 100)}%`;
  dom.emptyGuide.classList.toggle("hidden", state.canvasItems.length > 0);
}

function screenToWorld(clientX, clientY) {
  const rect = dom.workspace.getBoundingClientRect();
  return {
    x: (clientX - rect.left - state.panX) / state.zoom,
    y: (clientY - rect.top - state.panY) / state.zoom
  };
}

// --- Canvas Chip DOM Management ---
const chipNodes = new Map(); // uid -> HTMLElement

function createCanvasChipNode(item, animatePop = true) {
  const el = ELEMENT_MAP.get(item.id);
  if (!el) return null;
  const div = document.createElement("div");
  div.className = "chip canvas-chip" +
    (el.milestone ? " milestone" : "") +
    (el.procedural ? " procedural" : "") +
    (animatePop ? " pop-in" : "");
  div.dataset.uid = item.uid;
  div.style.left = `${item.x}px`;
  div.style.top = `${item.y}px`;
  div.title = el.lore || el.name;

  let badgeHtml = "";
  if (item.firstBadge) {
    badgeHtml = `<span class="first-badge">${el.official ? "✨ Hito Malandriner" : "✨ Primer Descubrimiento"}</span>`;
  }
  div.innerHTML = `<span class="emoji">${el.emoji}</span><span class="label">${el.name}</span>${badgeHtml}`;

  // Double click duplicates chip
  div.addEventListener("dblclick", (e) => {
    e.stopPropagation();
    sfx.pickup();
    spawnCanvasChip(item.id, item.x + 26, item.y + 26, false);
    saveState();
  });

  // Right click deletes chip
  div.addEventListener("contextmenu", (e) => {
    e.preventDefault();
    e.stopPropagation();
    sfx.delete();
    removeCanvasChip(item.uid);
    saveState();
  });

  // Pointer drag start on canvas chip
  div.addEventListener("pointerdown", (e) => {
    if (e.button !== 0) return;
    e.stopPropagation();
    startCanvasChipDrag(e, item, div);
  });

  dom.world.appendChild(div);
  chipNodes.set(item.uid, div);
  return div;
}

function spawnCanvasChip(id, x, y, firstBadge = false) {
  const item = { uid: uidCounter++, id, x, y, firstBadge };
  state.canvasItems.push(item);
  createCanvasChipNode(item, true);
  dom.emptyGuide.classList.add("hidden");
  return item;
}

function removeCanvasChip(uid) {
  const idx = state.canvasItems.findIndex(c => c.uid === uid);
  if (idx !== -1) state.canvasItems.splice(idx, 1);
  const node = chipNodes.get(uid);
  if (node) {
    node.remove();
    chipNodes.delete(uid);
  }
  dom.emptyGuide.classList.toggle("hidden", state.canvasItems.length > 0);
}

function showFloatingFormula(x, y, text) {
  const f = document.createElement("div");
  f.className = "floating-formula";
  f.style.left = `${x}px`;
  f.style.top = `${y}px`;
  f.textContent = text;
  dom.world.appendChild(f);
  setTimeout(() => f.remove(), 1250);
}

// --- Sidebar & Stats Rendering ---
function updateStatsAndHeader() {
  const officialDiscovered = state.discovered.filter(id => {
    const el = ELEMENT_MAP.get(id);
    return el && el.official;
  }).length;
  const customDiscovered = state.discovered.length - officialDiscovered;
  const totalOfficial = OFFICIAL_ELEMENTS.length;

  dom.statsOfficial.textContent = `⚡ Oficiales: ${officialDiscovered} / ${totalOfficial}`;
  dom.statsExtra.textContent = `✨ Inventos: ${customDiscovered}`;
  const pct = Math.min(100, (officialDiscovered / totalOfficial) * 100);
  dom.progressFill.style.width = `${pct.toFixed(1)}%`;

  dom.btnInfinite.classList.toggle("active-mode", state.infiniteMode);
  dom.infiniteLabel.textContent = state.infiniteMode ? "ON" : "OFF";
  dom.btnSound.textContent = state.sound ? "🔊" : "🔇";
  dom.btnTheme.textContent = state.theme === "dark" ? "☀️" : "🌙";
  document.documentElement.setAttribute("data-theme", state.theme);
}

function renderInventory() {
  updateStatsAndHeader();
  const availCombos = getElementsWithAvailableCombos();
  const q = state.search.trim().toLowerCase();

  let items = state.discovered
    .map((id, index) => ({ el: ELEMENT_MAP.get(id), index }))
    .filter(x => x.el);

  if (state.filter === "official") {
    items = items.filter(x => x.el.official);
  } else if (state.filter === "custom") {
    items = items.filter(x => !x.el.official);
  } else if (state.filter === "combos") {
    items = items.filter(x => availCombos.has(x.el.id));
  }

  if (q) {
    items = items.filter(x =>
      x.el.name.toLowerCase().includes(q) ||
      x.el.emoji.includes(q) ||
      (x.el.lore && x.el.lore.toLowerCase().includes(q))
    );
  }

  if (state.sort === "recent") {
    items.reverse();
  } else if (state.sort === "az") {
    items.sort((a, b) => a.el.name.localeCompare(b.el.name, "es"));
  } else if (state.sort === "cat") {
    items.sort((a, b) => (a.el.cat || "").localeCompare(b.el.cat || "") || a.el.name.localeCompare(b.el.name, "es"));
  }

  dom.inventoryList.innerHTML = "";
  if (items.length === 0) {
    const empty = document.createElement("div");
    empty.className = "inv-empty";
    empty.textContent = q
      ? "No hay ningún elemento que coincida con tu búsqueda."
      : state.filter === "combos"
        ? "¡No quedan recetas directas con este filtro! Prueba otro filtro o el Modo Infinito."
        : "Aún no tienes elementos en esta categoría.";
    dom.inventoryList.appendChild(empty);
    return;
  }

  const frag = document.createDocumentFragment();
  for (const { el } of items) {
    const chip = document.createElement("div");
    chip.className = "chip" + (el.milestone ? " milestone" : "") + (el.procedural ? " procedural" : "");
    chip.title = el.lore || el.name;

    const hasCombo = availCombos.has(el.id);
    const dotHtml = hasCombo
      ? `<span class="combo-dot" title="Tiene combinaciones oficiales por descubrir"></span>`
      : el.milestone
        ? `<span class="milestone-dot" title="Hito de Web Reactiva"></span>`
        : "";

    chip.innerHTML = `<span class="emoji">${el.emoji}</span><span class="label">${el.name}</span>${dotHtml}`;

    chip.addEventListener("pointerdown", (e) => {
      if (e.button !== 0) return;
      startSidebarDragOrClick(e, el);
    });

    frag.appendChild(chip);
  }
  dom.inventoryList.appendChild(frag);
}

// --- Combination Resolution ---
function combineElements(itemA, itemB, dropX, dropY) {
  const elA = ELEMENT_MAP.get(itemA.id);
  const elB = ELEMENT_MAP.get(itemB.id);
  if (!elA || !elB) return false;

  const key = pairKey(elA.id, elB.id);
  let resultEl = null;

  if (RECIPE_MAP.has(key)) {
    resultEl = ELEMENT_MAP.get(RECIPE_MAP.get(key));
  } else if (state.unlockedRecipes[key] && ELEMENT_MAP.has(state.unlockedRecipes[key])) {
    resultEl = ELEMENT_MAP.get(state.unlockedRecipes[key]);
  } else if (state.infiniteMode) {
    resultEl = createProceduralElement(elA, elB);
  }

  if (!resultEl) {
    // Strict Official Mode & no recipe found: bounce gently + give helpful malandriner feedback
    sfx.fail();
    const nodeA = chipNodes.get(itemA.uid);
    const nodeB = chipNodes.get(itemB.uid);
    itemA.x = itemB.x + (Math.random() > 0.5 ? 58 : -58);
    itemA.y = itemB.y + 34;
    if (nodeA) {
      nodeA.style.left = `${itemA.x}px`;
      nodeA.style.top = `${itemA.y}px`;
      nodeA.classList.remove("shake");
      void nodeA.offsetWidth;
      nodeA.classList.add("shake");
    }
    if (nodeB) {
      nodeB.classList.remove("shake");
      void nodeB.offsetWidth;
      nodeB.classList.add("shake");
    }
    const remA = countRemainingCombosFor(elA.id);
    const remB = countRemainingCombosFor(elB.id);
    showToast({
      emoji: "🤔",
      tag: "Sin receta oficial",
      title: `${elA.name} + ${elB.name} no cuaja`,
      desc: `Pista: ${elA.emoji} tiene ${remA} combo(s) disponible(s) y ${elB.emoji} tiene ${remB}. (O activa ∞ Modo Infinito arriba).`,
      info: true,
      duration: 3400
    });
    return false;
  }

  // Consume both source chips and create result!
  removeCanvasChip(itemA.uid);
  removeCanvasChip(itemB.uid);

  const isNew = !state.discovered.includes(resultEl.id);
  state.unlockedRecipes[key] = resultEl.id;

  if (!resultEl.official) {
    state.customElements[resultEl.id] = resultEl;
  }

  let showFirstBadge = false;
  if (isNew) {
    state.discovered.push(resultEl.id);
    if (resultEl.milestone || resultEl.procedural) {
      state.firstDiscoveries.push(resultEl.id);
      showFirstBadge = true;
    }
    sfx.discover(Boolean(resultEl.milestone || resultEl.procedural));
    spawnParticles(dropX, dropY, true);

    showToast({
      emoji: resultEl.emoji,
      tag: resultEl.official
        ? (resultEl.milestone ? "🏆 ¡Hito Web Reactiva Descubierto!" : "⚡ ¡Nuevo Elemento Oficial!")
        : "✨ ¡Primer Descubrimiento Malandriner!",
      title: resultEl.name,
      desc: resultEl.lore
    });

    dom.brandQuote.textContent = `${resultEl.emoji} ${resultEl.name}: ${resultEl.lore}`;
    renderInventory();
  } else {
    sfx.combine();
    spawnParticles(dropX, dropY, false);
  }

  showFloatingFormula(dropX, dropY, `${elA.emoji} + ${elB.emoji} = ${resultEl.emoji} ${resultEl.name}`);
  spawnCanvasChip(resultEl.id, dropX, dropY, showFirstBadge);
  saveState();
  return true;
}

// --- Dragging & Merge Target Detection ---
const MERGE_DISTANCE = 64;

function findNearestCanvasItem(worldX, worldY, excludeUid = null) {
  let best = null;
  let bestDist = MERGE_DISTANCE;
  for (const it of state.canvasItems) {
    if (it.uid === excludeUid) continue;
    const d = Math.hypot(it.x - worldX, it.y - worldY);
    if (d < bestDist) {
      bestDist = d;
      best = it;
    }
  }
  return best;
}

function clearMergeHighlights() {
  for (const node of chipNodes.values()) {
    node.classList.remove("merge-target");
  }
}

function isOverSidebar(clientX, clientY) {
  const r = dom.sidebar.getBoundingClientRect();
  return clientX >= r.left && clientX <= r.right && clientY >= r.top && clientY <= r.bottom;
}

function startCanvasChipDrag(e, item, node) {
  sfx.pickup();
  const pointerId = e.pointerId;
  node.setPointerCapture(pointerId);
  node.classList.add("dragging");

  // Bring item to end of array so z-order stays fresh
  const idx = state.canvasItems.indexOf(item);
  if (idx !== -1) {
    state.canvasItems.splice(idx, 1);
    state.canvasItems.push(item);
    dom.world.appendChild(node);
  }

  const startWorld = screenToWorld(e.clientX, e.clientY);
  const offsetX = item.x - startWorld.x;
  const offsetY = item.y - startWorld.y;
  let lastX = e.clientX;
  let hoveredTarget = null;

  function onMove(ev) {
    if (ev.pointerId !== pointerId) return;
    const vx = Math.max(-5, Math.min(5, (ev.clientX - lastX) * 0.25));
    lastX = ev.clientX;

    const w = screenToWorld(ev.clientX, ev.clientY);
    item.x = w.x + offsetX;
    item.y = w.y + offsetY;
    node.style.left = `${item.x}px`;
    node.style.top = `${item.y}px`;
    node.style.transform = `translate(-50%, -50%) scale(1.05) rotate(${vx}deg)`;

    const overTrash = isOverSidebar(ev.clientX, ev.clientY);
    dom.sidebar.classList.toggle("trash-hover", overTrash);

    clearMergeHighlights();
    if (!overTrash) {
      hoveredTarget = findNearestCanvasItem(item.x, item.y, item.uid);
      if (hoveredTarget) {
        const tNode = chipNodes.get(hoveredTarget.uid);
        if (tNode) tNode.classList.add("merge-target");
      }
    } else {
      hoveredTarget = null;
    }
  }

  function onUp(ev) {
    if (ev.pointerId !== pointerId) return;
    node.removeEventListener("pointermove", onMove);
    node.removeEventListener("pointerup", onUp);
    node.removeEventListener("pointercancel", onUp);
    node.classList.remove("dragging");
    node.style.transform = "";
    dom.sidebar.classList.remove("trash-hover");
    clearMergeHighlights();

    if (isOverSidebar(ev.clientX, ev.clientY)) {
      sfx.delete();
      removeCanvasChip(item.uid);
      saveState();
      return;
    }

    if (hoveredTarget) {
      const midX = (item.x + hoveredTarget.x) / 2;
      const midY = (item.y + hoveredTarget.y) / 2;
      combineElements(item, hoveredTarget, midX, midY);
    } else {
      sfx.drop();
      saveState();
    }
  }

  node.addEventListener("pointermove", onMove);
  node.addEventListener("pointerup", onUp);
  node.addEventListener("pointercancel", onUp);
}

// Spawn smartly near center of workspace when clicking an inventory item
function spawnAtSmartSpot(elId) {
  const rect = dom.workspace.getBoundingClientRect();
  const centerW = screenToWorld(rect.left + rect.width * 0.5, rect.top + rect.height * 0.52);
  const count = state.canvasItems.length;
  const angle = count * 2.39996; // golden angle spiral so chips don't stack blindly
  const radius = count === 0 ? 0 : Math.min(180, 38 + Math.sqrt(count) * 32);
  const x = centerW.x + Math.cos(angle) * radius;
  const y = centerW.y + Math.sin(angle) * radius * 0.72;
  sfx.pickup();
  spawnCanvasChip(elId, x, y, false);
  saveState();
}

function startSidebarDragOrClick(e, el) {
  const startX = e.clientX;
  const startY = e.clientY;
  let dragging = false;
  let hoveredTarget = null;

  function onMove(ev) {
    const dist = Math.hypot(ev.clientX - startX, ev.clientY - startY);
    if (!dragging && dist > 7) {
      dragging = true;
      sfx.pickup();
      dom.dragGhost.querySelector(".emoji").textContent = el.emoji;
      dom.dragGhost.querySelector(".label").textContent = el.name;
      dom.dragGhost.style.display = "inline-flex";
    }
    if (dragging) {
      dom.dragGhost.style.left = `${ev.clientX}px`;
      dom.dragGhost.style.top = `${ev.clientY}px`;
      clearMergeHighlights();
      if (!isOverSidebar(ev.clientX, ev.clientY)) {
        const w = screenToWorld(ev.clientX, ev.clientY);
        hoveredTarget = findNearestCanvasItem(w.x, w.y, null);
        if (hoveredTarget) {
          const tNode = chipNodes.get(hoveredTarget.uid);
          if (tNode) tNode.classList.add("merge-target");
        }
      } else {
        hoveredTarget = null;
      }
    }
  }

  function onUp(ev) {
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerup", onUp);
    window.removeEventListener("pointercancel", onUp);
    dom.dragGhost.style.display = "none";
    clearMergeHighlights();

    if (!dragging) {
      spawnAtSmartSpot(el.id);
      return;
    }

    if (!isOverSidebar(ev.clientX, ev.clientY)) {
      const w = screenToWorld(ev.clientX, ev.clientY);
      const created = spawnCanvasChip(el.id, w.x, w.y, false);
      if (hoveredTarget) {
        combineElements(created, hoveredTarget, hoveredTarget.x, hoveredTarget.y);
      } else {
        sfx.drop();
        saveState();
      }
    }
  }

  window.addEventListener("pointermove", onMove);
  window.addEventListener("pointerup", onUp);
  window.addEventListener("pointercancel", onUp);
}

// --- Workspace Panning & Zooming ---
dom.workspace.addEventListener("pointerdown", (e) => {
  if (e.target !== dom.workspace && e.target !== dom.world) return;
  if (e.button !== 0 && e.button !== 1) return;
  const pointerId = e.pointerId;
  dom.workspace.setPointerCapture(pointerId);
  dom.workspace.classList.add("panning");
  const startX = e.clientX - state.panX;
  const startY = e.clientY - state.panY;

  function onMove(ev) {
    if (ev.pointerId !== pointerId) return;
    state.panX = ev.clientX - startX;
    state.panY = ev.clientY - startY;
    updateWorldTransform();
  }
  function onUp(ev) {
    if (ev.pointerId !== pointerId) return;
    dom.workspace.classList.remove("panning");
    dom.workspace.removeEventListener("pointermove", onMove);
    dom.workspace.removeEventListener("pointerup", onUp);
    dom.workspace.removeEventListener("pointercancel", onUp);
  }
  dom.workspace.addEventListener("pointermove", onMove);
  dom.workspace.addEventListener("pointerup", onUp);
  dom.workspace.addEventListener("pointercancel", onUp);
});

dom.workspace.addEventListener("wheel", (e) => {
  e.preventDefault();
  const rect = dom.workspace.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;
  const prevZoom = state.zoom;
  const delta = e.deltaY < 0 ? 1.09 : 0.91;
  const nextZoom = Math.max(0.45, Math.min(1.85, prevZoom * delta));
  state.panX = mx - ((mx - state.panX) / prevZoom) * nextZoom;
  state.panY = my - ((my - state.panY) / prevZoom) * nextZoom;
  state.zoom = nextZoom;
  updateWorldTransform();
}, { passive: false });

// --- Smart Hint System ---
function giveSmartHint() {
  const discSet = new Set(state.discovered);
  const candidates = [];
  for (const [k, resId] of RECIPE_MAP.entries()) {
    if (discSet.has(resId)) continue;
    const [a, b] = k.split("+");
    if (discSet.has(a) && discSet.has(b)) {
      candidates.push({ a: ELEMENT_MAP.get(a), b: ELEMENT_MAP.get(b), res: ELEMENT_MAP.get(resId) });
    }
  }

  if (candidates.length === 0) {
    showToast({
      emoji: "👑",
      tag: "¡Alquimia Oficial Completada!",
      title: "¡Has descubierto todos los elementos oficiales!",
      desc: "Ya eres Leyenda Malandriner. Activa ∞ Modo Infinito para seguir creando inventos locos.",
      info: true
    });
    return;
  }

  // Prefer milestone discoveries or pick random available combo
  const milestoneHits = candidates.filter(c => c.res.milestone);
  const pickPool = milestoneHits.length > 0 && Math.random() < 0.55 ? milestoneHits : candidates;
  const chosen = pickPool[Math.floor(Math.random() * pickPool.length)];

  sfx.pickup();
  showToast({
    emoji: "💡",
    tag: `Pista Malandriner (${candidates.length} combos disponibles)`,
    title: `Prueba juntar ${chosen.a.emoji} ${chosen.a.name} + ${chosen.b.emoji} ${chosen.b.name}`,
    desc: `Pista del resultado: pertenece a «${CATEGORIES[chosen.res.cat]}».`,
    info: true,
    actionText: "✨ Sacar ambos a la mesa",
    onAction: () => {
      const rect = dom.workspace.getBoundingClientRect();
      const c = screenToWorld(rect.left + rect.width * 0.5, rect.top + rect.height * 0.52);
      spawnCanvasChip(chosen.a.id, c.x - 62, c.y, false);
      spawnCanvasChip(chosen.b.id, c.x + 62, c.y, false);
      sfx.pickup();
      saveState();
    },
    duration: 7000
  });
}

// --- Códice Malandriner Modal ---
function renderCodexModal() {
  const discSet = new Set(state.discovered);
  dom.modalBody.innerHTML = "";

  if (state.activeModalTab === "elements") {
    // Reverse map: resultId -> unlocked recipe pair
    const recipeByResult = {};
    for (const [k, rId] of Object.entries(state.unlockedRecipes)) {
      if (!recipeByResult[rId]) recipeByResult[rId] = k;
    }

    for (const [catKey, catLabel] of Object.entries(CATEGORIES)) {
      const catEls = OFFICIAL_ELEMENTS.filter(e => e.cat === catKey);
      const unlockedCount = catEls.filter(e => discSet.has(e.id)).length;

      const sec = document.createElement("div");
      sec.className = "cat-section";
      sec.innerHTML = `<div class="cat-title"><span>${catLabel}</span><span>${unlockedCount} / ${catEls.length}</span></div>`;

      const grid = document.createElement("div");
      grid.className = "codex-grid";

      for (const el of catEls) {
        const unlocked = discSet.has(el.id);
        const card = document.createElement("div");
        card.className = "codex-item" + (unlocked ? "" : " locked");

        if (unlocked) {
          let recText = el.starter ? "🌱 Elemento inicial" : "";
          if (recipeByResult[el.id]) {
            const [ra, rb] = recipeByResult[el.id].split("+");
            const ea = ELEMENT_MAP.get(ra);
            const eb = ELEMENT_MAP.get(rb);
            if (ea && eb) recText = `🧪 ${ea.emoji} ${ea.name} + ${eb.emoji} ${eb.name}`;
          }
          card.innerHTML = `
            <div class="codex-item-top"><span>${el.emoji}</span><span>${el.name}</span></div>
            <div class="codex-item-lore">${el.lore}</div>
            ${recText ? `<div class="codex-item-recipe">${recText}</div>` : ""}
          `;
          card.title = "Haz clic para enviar a la mesa";
          card.addEventListener("click", () => {
            spawnAtSmartSpot(el.id);
            dom.codexModal.classList.remove("open");
          });
        } else {
          card.innerHTML = `
            <div class="codex-item-top"><span>🔒</span><span>???</span></div>
            <div class="codex-item-lore">Elemento oculto de ${catLabel.replace(/^[^\s]+\s/, "")}.</div>
          `;
        }
        grid.appendChild(card);
      }
      sec.appendChild(grid);
      dom.modalBody.appendChild(sec);
    }
  } else if (state.activeModalTab === "achievements") {
    const officialCount = state.discovered.filter(id => ELEMENT_MAP.get(id)?.official).length;
    const grid = document.createElement("div");
    grid.className = "ach-grid";

    for (const ach of ACHIEVEMENTS) {
      const ok = ach.countReq
        ? officialCount >= ach.countReq
        : ach.req.every(r => discSet.has(r));

      const card = document.createElement("div");
      card.className = "ach-card" + (ok ? " unlocked" : "");
      card.innerHTML = `
        <div class="ach-icon">${ach.icon}</div>
        <div>
          <div style="font-weight:800;font-size:14px;">${ach.title} ${ok ? "✅" : ""}</div>
          <div style="font-size:12px;color:var(--text-muted);margin-top:3px;line-height:1.38;">${ach.desc}</div>
        </div>
      `;
      grid.appendChild(card);
    }
    dom.modalBody.appendChild(grid);
  } else if (state.activeModalTab === "recipes") {
    const entries = Object.entries(state.unlockedRecipes).reverse();
    if (entries.length === 0) {
      dom.modalBody.innerHTML = `<div class="inv-empty">Aún no has registrado ninguna combinación. ¡Junta dos fichas en la mesa!</div>`;
      return;
    }
    for (const [k, resId] of entries) {
      const [a, b] = k.split("+");
      const ea = ELEMENT_MAP.get(a);
      const eb = ELEMENT_MAP.get(b);
      const er = ELEMENT_MAP.get(resId);
      if (!ea || !eb || !er) continue;

      const row = document.createElement("div");
      row.className = "recipe-row";
      row.innerHTML = `
        <span><strong>${ea.emoji} ${ea.name}</strong> + <strong>${eb.emoji} ${eb.name}</strong></span>
        <span>➔ <strong>${er.emoji} ${er.name}</strong></span>
      `;
      dom.modalBody.appendChild(row);
    }
  }
}

// --- UI Controls Event Bindings ---
dom.searchInput.addEventListener("input", () => {
  state.search = dom.searchInput.value;
  dom.searchClear.style.display = state.search ? "block" : "none";
  renderInventory();
});

dom.searchClear.addEventListener("click", () => {
  state.search = "";
  dom.searchInput.value = "";
  dom.searchClear.style.display = "none";
  renderInventory();
});

dom.filterTabs.addEventListener("click", (e) => {
  const btn = e.target.closest(".tab-chip");
  if (!btn) return;
  state.filter = btn.dataset.filter;
  for (const b of dom.filterTabs.querySelectorAll(".tab-chip")) {
    b.classList.toggle("active", b === btn);
  }
  renderInventory();
});

dom.sortSelect.addEventListener("change", () => {
  state.sort = dom.sortSelect.value;
  renderInventory();
});

dom.btnInfinite.addEventListener("click", () => {
  state.infiniteMode = !state.infiniteMode;
  sfx.pickup();
  updateStatsAndHeader();
  saveState();
  showToast({
    emoji: state.infiniteMode ? "∞" : "🎯",
    tag: "Modo de Alquimia",
    title: state.infiniteMode ? "Modo Infinito ACTIVADO" : "Modo Solo Recetas Oficiales",
    desc: state.infiniteMode
      ? "Cualquier par sin receta oficial fusionará un invento malandriner único."
      : "Solo combinarán las recetas oficiales de los 112 elementos de Web Reactiva.",
    info: true,
    duration: 3000
  });
});

dom.btnSound.addEventListener("click", () => {
  state.sound = !state.sound;
  sfx.enabled = state.sound;
  if (state.sound) sfx.pickup();
  updateStatsAndHeader();
  saveState();
});

dom.btnTheme.addEventListener("click", () => {
  state.theme = state.theme === "dark" ? "light" : "dark";
  sfx.pickup();
  updateStatsAndHeader();
  saveState();
});

dom.btnHint.addEventListener("click", giveSmartHint);

dom.btnStarterPack.addEventListener("click", () => {
  const rect = dom.workspace.getBoundingClientRect();
  const c = screenToWorld(rect.left + rect.width * 0.5, rect.top + rect.height * 0.52);
  const offsets = [[-85, -45], [85, -45], [-85, 45], [85, 45]];
  ["codigo", "microfono", "cafe", "curiosidad"].forEach((id, i) => {
    spawnCanvasChip(id, c.x + offsets[i][0], c.y + offsets[i][1], false);
  });
  sfx.pickup();
  saveState();
});

dom.btnClear.addEventListener("click", () => {
  if (state.canvasItems.length === 0) return;
  sfx.delete();
  state.canvasItems = [];
  chipNodes.clear();
  dom.world.innerHTML = "";
  dom.emptyGuide.classList.remove("hidden");
  saveState();
});

dom.btnCenter.addEventListener("click", () => {
  state.panX = 0;
  state.panY = 0;
  state.zoom = 1;
  sfx.pickup();
  updateWorldTransform();
});

dom.btnCodex.addEventListener("click", () => {
  sfx.pickup();
  renderCodexModal();
  dom.codexModal.classList.add("open");
});

dom.modalClose.addEventListener("click", () => {
  dom.codexModal.classList.remove("open");
});

dom.codexModal.addEventListener("click", (e) => {
  if (e.target === dom.codexModal) dom.codexModal.classList.remove("open");
});

dom.modalTabs.addEventListener("click", (e) => {
  const btn = e.target.closest(".modal-tab");
  if (!btn) return;
  state.activeModalTab = btn.dataset.mtab;
  for (const b of dom.modalTabs.querySelectorAll(".modal-tab")) {
    b.classList.toggle("active", b === btn);
  }
  renderCodexModal();
});

dom.btnReset.addEventListener("click", () => {
  if (!confirm("¿Seguro que quieres borrar todo tu progreso malandriner y empezar desde los 4 elementos iniciales?")) return;
  localStorage.removeItem(STORAGE_KEY);
  location.reload();
});

// Rotate subtle Web Reactiva quotes occasionally when idle
setInterval(() => {
  const q = DANI_QUOTES[Math.floor(Math.random() * DANI_QUOTES.length)];
  dom.brandQuote.textContent = q;
}, 22000);

// --- Boot Game ---
function init() {
  resizeFxCanvas();
  const hadSave = loadState();
  sfx.enabled = state.sound;
  updateWorldTransform();
  renderInventory();

  if (hadSave && state.canvasItems.length > 0) {
    const savedItems = [...state.canvasItems];
    state.canvasItems = [];
    for (const it of savedItems) {
      const itemObj = { uid: uidCounter++, id: it.id, x: it.x, y: it.y, firstBadge: Boolean(it.firstBadge) };
      state.canvasItems.push(itemObj);
      createCanvasChipNode(itemObj, false);
    }
    dom.emptyGuide.classList.toggle("hidden", state.canvasItems.length > 0);
  } else if (!hadSave) {
    // Place the 4 starter elements invitingly in the middle on first launch!
    requestAnimationFrame(() => {
      const rect = dom.workspace.getBoundingClientRect();
      const cx = rect.width * 0.5;
      const cy = rect.height * 0.53;
      const spots = [[-95, -48], [95, -48], [-95, 48], [95, 48]];
      ["codigo", "microfono", "cafe", "curiosidad"].forEach((id, i) => {
        spawnCanvasChip(id, cx + spots[i][0], cy + spots[i][1], false);
      });
      saveState();
    });
  }

  tickParticles();
}

init();

