+      modalBody: document.getElementById("modal-body")
+    };
+
+    // --- Particle Burst System ---
+    const fxCtx = dom.fxCanvas.getContext("2d");
+    const particles = [];
+
+    function resizeFxCanvas() {
+      const rect = dom.workspace.getBoundingClientRect();
+      const dpr = window.devicePixelRatio || 1;
+      dom.fxCanvas.width = rect.width * dpr;
+      dom.fxCanvas.height = rect.height * dpr;
+      fxCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
+    }
+    window.addEventListener("resize", resizeFxCanvas);
+
+    function spawnParticles(worldX, worldY, isSpecial = false) {
+      const sx = worldX * state.zoom + state.panX;
+      const sy = worldY * state.zoom + state.panY;
+      const colors = isSpecial
+        ? ["#facc15", "#f59e0b", "#6366f1", "#ec4899", "#10b981"]
+        : ["#6366f1", "#f59e0b", "#3b82f6", "#a855f7"];
+      const count = isSpecial ? 34 : 18;
+      for (let i = 0; i < count; i++) {
+        const angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.4;
+        const speed = (isSpecial ? 2.4 : 1.6) + Math.random() * (isSpecial ? 4.2 : 2.6);
+        particles.push({
+          x: sx,
+          y: sy,
+          vx: Math.cos(angle) * speed,
+          vy: Math.sin(angle) * speed - 0.6,
+          r: 2.5 + Math.random() * (isSpecial ? 3.5 : 2.2),
+          alpha: 1,
+          color: colors[i % colors.length]
+        });
+      }
+    }
+
+    function tickParticles() {
+      if (particles.length > 0) {
+        const rect = dom.workspace.getBoundingClientRect();
+        fxCtx.clearRect(0, 0, rect.width, rect.height);
+        for (let i = particles.length - 1; i >= 0; i--) {
+          const p = particles[i];
+          p.x += p.vx;
+          p.y += p.vy;
+          p.vy += 0.08;
+          p.alpha -= 0.028;
+          if (p.alpha <= 0) {
+            particles.splice(i, 1);
+            continue;
+          }
+          fxCtx.globalAlpha = p.alpha;
+          fxCtx.fillStyle = p.color;
+          fxCtx.beginPath();
+          fxCtx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
+          fxCtx.fill();
+        }
+        fxCtx.globalAlpha = 1;
+      }
+      requestAnimationFrame(tickParticles);
+    }
+
+    // --- Helper: Compute which discovered elements still have undiscovered official combos ---
+    function getElementsWithAvailableCombos() {
+      const discSet = new Set(state.discovered);
+      const hasCombo = new Set();
+      for (const [k, resId] of RECIPE_MAP.entries()) {
+        if (discSet.has(resId)) continue;
+        const [a, b] = k.split("+");
+        if (discSet.has(a) && discSet.has(b)) {
+          hasCombo.add(a);
+          hasCombo.add(b);
+        }
+      }
+      return hasCombo;
+    }
+
+    function countRemainingCombosFor(elId) {
+      const discSet = new Set(state.discovered);
+      let count = 0;
+      for (const [k, resId] of RECIPE_MAP.entries()) {
+        if (discSet.has(resId)) continue;
+        const [a, b] = k.split("+");
+        if ((a === elId && discSet.has(b)) || (b === elId && discSet.has(a))) {
+          count++;
+        }
+      }
+      return count;
+    }
+
+    // --- Toast Notifications ---
+    function showToast({ emoji, tag, title, desc, info = false, actionText = null, onAction = null, duration = 4600 }) {
+      while (dom.toastContainer.children.length >= 2) {
+        dom.toastContainer.firstChild.remove();
+      }
+      const card = document.createElement("div");
+      card.className = "discovery-toast" + (info ? " info-toast" : "");
+      card.innerHTML = `
+        <div class="toast-emoji">${emoji}</div>
+        <div class="toast-body">
+          <div class="toast-tag">${tag}</div>
+          <div class="toast-title">${title}</div>
+          <div class="toast-desc">${desc}</div>
+        </div>
+      `;
+      if (actionText && onAction) {
+        const btn = document.createElement("button");
+        btn.className = "toast-action";
+        btn.textContent = actionText;
+        btn.addEventListener("click", () => {
+          onAction();
+          card.remove();
+        });
+        card.querySelector(".toast-body").appendChild(btn);
+      }
+      dom.toastContainer.appendChild(card);
+      setTimeout(() => {
+        if (card.parentNode) card.remove();
+      }, duration);
+    }
+
+    // --- World Transform (Pan & Zoom) ---
+    function updateWorldTransform() {
+      dom.world.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.zoom})`;
+      dom.workspace.style.backgroundPosition = `${state.panX}px ${state.panY}px`;
+      const grid = 24 * state.zoom;
+      dom.workspace.style.backgroundSize = `${grid}px ${grid}px`;
+      dom.zoomLabel.textContent = `${Math.round(state.zoom * 100)}%`;
+      dom.emptyGuide.classList.toggle("hidden", state.canvasItems.length > 0);
+    }
+
+    function screenToWorld(clientX, clientY) {
+      const rect = dom.workspace.getBoundingClientRect();
+      return {
+        x: (clientX - rect.left - state.panX) / state.zoom,
+        y: (clientY - rect.top - state.panY) / state.zoom
+      };
+    }
+
+    // --- Canvas Chip DOM Management ---
+    const chipNodes = new Map(); // uid -> HTMLElement
+
+    function createCanvasChipNode(item, animatePop = true) {
+      const el = ELEMENT_MAP.get(item.id);
+      if (!el) return null;
+      const div = document.createElement("div");
+      div.className = "chip canvas-chip" +
+        (el.milestone ? " milestone" : "") +
+        (el.procedural ? " procedural" : "") +
+        (animatePop ? " pop-in" : "");
+      div.dataset.uid = item.uid;
+      div.style.left = `${item.x}px`;
+      div.style.top = `${item.y}px`;
+      div.title = el.lore || el.name;
+
+      let badgeHtml = "";
+      if (item.firstBadge) {
+        badgeHtml = `<span class="first-badge">${el.official ? "✨ Hito Malandriner" : "✨ Primer Descubrimiento"}</span>`;
+      }
+      div.innerHTML = `<span class="emoji">${el.emoji}</span><span class="label">${el.name}</span>${badgeHtml}`;
+
+      // Double click duplicates chip
+      div.addEventListener("dblclick", (e) => {
+        e.stopPropagation();
+        sfx.pickup();
+        spawnCanvasChip(item.id, item.x + 26, item.y + 26, false);
+        saveState();
+      });
+
+      // Right click deletes chip
+      div.addEventListener("contextmenu", (e) => {
+        e.preventDefault();
+        e.stopPropagation();
+        sfx.delete();
+        removeCanvasChip(item.uid);
+        saveState();
+      });
+
+      // Pointer drag start on canvas chip
+      div.addEventListener("pointerdown", (e) => {
+        if (e.button !== 0) return;
+        e.stopPropagation();
+        startCanvasChipDrag(e, item, div);
+      });
+
+      dom.world.appendChild(div);
+      chipNodes.set(item.uid, div);
+      return div;
+    }
+
+    function spawnCanvasChip(id, x, y, firstBadge = false) {
+      const item = { uid: uidCounter++, id, x, y, firstBadge };
+      state.canvasItems.push(item);
+      createCanvasChipNode(item, true);
+      dom.emptyGuide.classList.add("hidden");
+      return item;
+    }
+
+    function removeCanvasChip(uid) {
+      const idx = state.canvasItems.findIndex(c => c.uid === uid);
+      if (idx !== -1) state.canvasItems.splice(idx, 1);
+      const node = chipNodes.get(uid);
+      if (node) {
+        node.remove();
+        chipNodes.delete(uid);
+      }
+      dom.emptyGuide.classList.toggle("hidden", state.canvasItems.length > 0);
+    }
+
+    function showFloatingFormula(x, y, text) {
+      const f = document.createElement("div");
+      f.className = "floating-formula";
+      f.style.left = `${x}px`;
+      f.style.top = `${y}px`;
+      f.textContent = text;
+      dom.world.appendChild(f);
+      setTimeout(() => f.remove(), 1250);
+    }
+
+    // --- Sidebar & Stats Rendering ---
+    function updateStatsAndHeader() {
+      const officialDiscovered = state.discovered.filter(id => {
+        const el = ELEMENT_MAP.get(id);
+        return el && el.official;
+      }).length;
+      const customDiscovered = state.discovered.length - officialDiscovered;
+      const totalOfficial = OFFICIAL_ELEMENTS.length;
+
+      dom.statsOfficial.textContent = `⚡ Oficiales: ${officialDiscovered} / ${totalOfficial}`;
+      dom.statsExtra.textContent = `✨ Inventos: ${customDiscovered}`;
+      const pct = Math.min(100, (officialDiscovered / totalOfficial) * 100);
+      dom.progressFill.style.width = `${pct.toFixed(1)}%`;
+
+      dom.btnInfinite.classList.toggle("active-mode", state.infiniteMode);
+      dom.infiniteLabel.textContent = state.infiniteMode ? "ON" : "OFF";
+      dom.btnSound.textContent = state.sound ? "🔊" : "🔇";
+      dom.btnTheme.textContent = state.theme === "dark" ? "☀️" : "🌙";
+      document.documentElement.setAttribute("data-theme", state.theme);
+    }
+
