+      for (const it of state.canvasItems) {
+        if (it.uid === excludeUid) continue;
+        const d = Math.hypot(it.x - worldX, it.y - worldY);
+        if (d < bestDist) {
+          bestDist = d;
+          best = it;
+        }
+      }
+      return best;
+    }
